mapper.select:
SELECT 
  FROM emp22_etc_leave
       LEFT OUTER JOIN apr01_appr apr01 ON apr01.apr01_appr_id = emp22_appr_id
 WHERE emp22_company_id = #{companyId}
   AND emp22_start_date  <=  #{closeDate}
   AND emp22_close_date  >=  #{startDate}
   AND UPPER(CONCAT(emp22_reason, emp22_note)) LIKE UPPER(#{searchText})
 ORDER BY emp22_start_date, emp22_close_date

SELECT 
  FROM emp22_etc_leave
       LEFT OUTER JOIN apr01_appr apr01 ON apr01.apr01_appr_id = emp22_appr_id
 WHERE emp22_etc_leave_id = #{etcLeaveId}
   AND emp22_company_id = #{companyId}

mapper.update:
UPDATE emp22_etc_leave
   SET emp22_days       = #{days},
       emp22_start_date = #{startDate},
       emp22_close_date = #{closeDate},
       emp22_reason     = #{reason},
       emp22_note       = #{note}

     , emp22_appr_id    = NULL

 WHERE emp22_etc_leave_id = #{etcLeaveId}
   AND emp22_company_id = #{companyId}

mapper.delete:
DELETE FROM emp22_etc_leave
 WHERE emp22_company_id = #{companyId}
   AND emp22_etc_leave_id IN
#{etcLeaveId}
